      `CLAIM_ADDED sheet=${sheet}-t by=uma person=Ada amount=1.00 date=2026-03-10`,
      `CLAIM_OPENED sheet=${sheet}-t by=uma person=Ada amount=1.00 date=2026-03-10 number=1`,
      `ROLLUP sheet=${sheet}-t by=uma person=Ada claimed=1.00 due-total=1.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet}-t by=uma claimed-total=1.00 due-total=1.00 overdue-total=0.00`,
      `STATEMENT sheet=${sheet}-t by=uma name=Ada due-total=1.00 claims=1`,
      `PERSON_TRANSFERRED sheet=${sheet}-t by=vic name=addie from=${sheet}`,
      `PERSON_MERGED sheet=${sheet}-t by=vic from=addie into=Ada`,
      `ROLLUP sheet=${sheet}-t by=vic person=Ada claimed=31.00 due-total=7.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet}-t by=vic claimed-total=31.00 due-total=7.00 overdue-total=0.00`
    ]);
  });
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.RequestBody;

public class MergePerson {
    // Only a steward (a delegation included) merges a person, into another person on the sheet; neither may be retired.
    public void merge(@RequestBody(required = false) MergeRequest body, @Val Person person, People people,
            Settings settings, Sheets sheets, ServerHttpConnection connection, Out<MergedPerson> mergedOut,
            Out<PersonResponse> responseOut) throws PersonMergeRefusedException {
        if (!Settings.STEWARD.equals(settings.role(person.sheetId(), Audit.user(connection).trim()))) {
            throw new PersonMergeRefusedException("Only a steward can merge people.");
        }
        Person into = body == null || body.intoId() == null ? null : people.find(person.sheetId(), body.intoId());
        if (into == null) {
            throw new PersonMergeRefusedException("Choose a person on this sheet to merge into.");
        }
        if (into.id() == person.id()) {
            throw new PersonMergeRefusedException("A person cannot be merged into themselves.");
        }
        if (person.retired() || into.retired()) {
            throw new PersonMergeRefusedException("A retired person cannot be merged.");
        }
        people.merge(person.sheetId(), person.id(), into.id());
        mergedOut.set(new MergedPerson(person, into));
        responseOut.set(PersonResponse.from(people.find(person.sheetId(), into.id()), sheets.today(person.sheetId())));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AuditPersonMerged {
    public void audit(@Val MergedPerson merged, ServerHttpConnection connection, Audit audit) {
        audit.record(Audit.line("PERSON_MERGED", merged.from().sheetId(), Audit.user(connection),
                "from=" + merged.from().name(), "into=" + merged.into().name()));
    }
}
package net.officefloor.hq.app.person;

/** A merge done: the person merged ({@code from}, now gone from the sheet) and the person they went into. */
public record MergedPerson(Person from, Person into) {
}
# POST /api/sheets/{sheetId}/people/{personId}/merge — a steward merges the person into another on the sheet. Body
# {"intoId":123}. The merged person's claims move to the other (numbers and dates kept, each losing any figure a
# statement bound, listed after the other's in the order they were added); their name and aliases become the
# other's aliases; their patrons and pool memberships go to the other, and anyone naming them as patron names the
# other instead. Their statements, holds, watchers and contact are dropped and they leave the sheet. 422, storing
# nothing, for anyone but a steward, the same person, no such person, or either of them retired; 404 for a person
# not on the sheet. Responds with the person merged into.
viewer:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: archived
  govern: [ transaction ]
archived:
  class: net.officefloor.hq.app.sheet.RefuseArchived
  next: snapshot
  govern: [ transaction ]
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  next: load
  govern: [ transaction ]
load:
  class: net.officefloor.hq.app.person.LoadPerson
  next: merge
  govern: [ transaction ]
merge:
  class: net.officefloor.hq.app.person.MergePerson
  next: audit
  govern: [ transaction ]
audit:
  class: net.officefloor.hq.app.person.AuditPersonMerged
  next: rollup
  govern: [ transaction ]
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  next: respond
  govern: [ transaction ]
respond:
  class: net.officefloor.hq.app.person.RespondWithEditedPerson
  govern: [ transaction ]

